  'ops5.alerts.title': 'अलर्ट नियम',
  'ops5.alerts.secondPersonNotice': 'ऐसा बदलाव जो अलर्ट को धीमा कर सकता है — नियम रोकना, किसी व्यक्ति को हटाना, या सीमा बढ़ाना — तभी लागू होता है जब कोई दूसरा व्यक्ति उसकी पुष्टि करे। तब तक मौजूदा नियम अलर्ट करता रहता है। हर बदलाव इस रिकॉर्ड के साथ दर्ज होता है कि किसने और क्यों किया।',
  'ops5.alerts.quietHoursNotice': 'प्राप्तकर्ता वे लोग हैं जिनके नाम नियम में दिए गए हैं। उनकी अपनी सूचना प्राथमिकताएँ और शांत घंटे लागू होते हैं, सिवाय उस अलर्ट के जिसे सर्वर गंभीर मानता है — वह उनके शांत घंटों में भी पहुँचता है। पसंदीदा चैनल नियम के साथ रखा जाता है, पर यह तय नहीं करता कि किसी को कैसे बताया जाए। अगर कोई अलर्ट को स्वीकार नहीं करता, तो किसी और को नहीं बताया जाता।',
